func TestFakeSessionState(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	f := tmuxctl.NewFake()

	if err := f.New(ctx, fakeName, fakeWorkDir); err != nil {
		t.Fatalf("New: %v", err)
	}
