		t.Error("creating a duplicate session succeeded")
	}
	if dir, ok := f.WorkDir(fakeName); !ok || dir != fakeWorkDir {
		t.Errorf("WorkDir = %q, %v, want %q, true", dir, ok, fakeWorkDir)
