// Calls hands out copies: a test that mangles what it read must not be able to
// rewrite the record every other assertion depends on.
func TestFakeCallsReturnsCopies(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	f := tmuxctl.NewFake()
	f.Seed(tmuxctl.SessionInfo{Name: fakeName, Managed: true})
	if err := f.Paste(ctx, fakeName, []byte("hello")); err != nil {
		t.Fatalf("Paste: %v", err)
	}

	first := f.Calls()
	first[0].Argv[1] = "clobbered"
	first[0].Stdin[0] = 'X'

	second := f.Calls()
	if second[0].Argv[1] != "load-buffer" {
		t.Errorf("recorded argv was mutated through Calls: %q", second[0].Argv)
	}
	if string(second[0].Stdin) != "hello" {
		t.Errorf("recorded stdin was mutated through Calls: %q", second[0].Stdin)
	}
}

// Destroy races the reaper by design, and the session cap is decided under
// concurrent creates. The fake has to survive being used that way.
func TestFakeIsSafeForConcurrentUse(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	f := tmuxctl.NewFake()

	const workers = 16
	var wg sync.WaitGroup
	wg.Add(workers)
	for i := range workers {
		go func() {
			defer wg.Done()

			// Indexed rather than 'a'+i: the alphabet is visibly as long as
			// workers, so the name stays in [a-z] by construction rather than by
			// the reader checking the bound (gosec G115).
			name := fakeName + "-" + string("abcdefghijklmnop"[i])
			if err := f.New(ctx, name, fakeWorkDir); err != nil {
				t.Errorf("New(%s): %v", name, err)
				return
			}
			if _, err := f.Has(ctx, name); err != nil {
				t.Errorf("Has(%s): %v", name, err)
			}
			if _, err := f.List(ctx); err != nil {
				t.Errorf("List: %v", err)
			}
			if err := f.Kill(ctx, name); err != nil {
				t.Errorf("Kill(%s): %v", name, err)
			}
			f.Calls()
		}()
	}
	wg.Wait()

	if got, err := f.List(ctx); err != nil {
		t.Fatalf("List: %v", err)
	} else if len(got) != 0 {
		t.Errorf("%d sessions survived, want 0", len(got))
	}
}

// TestLivenessOfSet pins the fake's half of the set comparison. The real List
// has tmux evaluate the same alternation (TestLivenessAlternatives), so the two
// must agree on every row here.
func TestLivenessOfSet(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		binary string
		pane   string
		want   tmuxctl.Liveness
	}{
		{"single name running", "claude", "claude", tmuxctl.LivenessRunning},
		{"single name stopped", "claude", "bash", tmuxctl.LivenessStopped},
		{"set matches first", "codex|node", "codex", tmuxctl.LivenessRunning},
		{"set matches second", "codex|node", "node", tmuxctl.LivenessRunning},
		{"set matches neither", "codex|node", "bash", tmuxctl.LivenessStopped},
		{"empty element never matches an empty pane", "codex||node", "", tmuxctl.LivenessStopped},
		{"empty element does not hide the rest", "codex||node", "node", tmuxctl.LivenessRunning},
		{"no binary is unknown", "", "bash", tmuxctl.LivenessUnknown},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			ctx := context.Background()
			f := tmuxctl.NewFake()
			if err := f.New(ctx, fakeName, fakeWorkDir); err != nil {
				t.Fatalf("New: %v", err)
			}
			if tt.binary != "" {
				if err := f.SetOption(ctx, fakeName, tmuxctl.OptionBinary, tt.binary); err != nil {
					t.Fatalf("SetOption: %v", err)
				}
			}
			f.SetPaneCommand(fakeName, tt.pane)

			sessions, err := f.List(ctx)
			if err != nil {
				t.Fatalf("List: %v", err)
			}
			if len(sessions) != 1 {
				t.Fatalf("List returned %d sessions, want 1", len(sessions))
			}
			if got := sessions[0].Claude; got != tt.want {
				t.Errorf("binary %q, pane %q: Claude = %q, want %q", tt.binary, tt.pane, got, tt.want)
			}
		})
	}
}

